// ---------------------------------------------------------------------------
// Liveness detection constants
// ---------------------------------------------------------------------------
// The CLIENT sends {"type":"ping"} every 5 s. The server responds with
// {"type":"pong"}. If a pong is missed, the client reconnects immediately.

// How often the client sends a ping to the server.
const PING_INTERVAL_MS = 5_000

// If no pong is received within this window, consider the connection
// dead and reconnect. This timeout is measured from the last ping sent,
// not from connect time, so the first timer tick always sends a ping
// instead of immediately declaring the socket stale.
const PONG_TIMEOUT_MS = 5_000

// Delay between reconnect attempts after a disconnect.
const RECONNECT_INTERVAL_MS = 5_000

tool_input.new_string:
import {EventEmitter} from "events"
import {AppState, AppStateStatus} from "react-native"

import restComms from "@/services/RestComms"
import {useConnectionStore} from "@/stores/connection"
import {getGlasesInfoPartial, useGlassesStore} from "@/stores/glasses"
import GlobalEventEmitter from "@/utils/GlobalEventEmitter"
import {BackgroundTimer} from "@/utils/timers"

// ---------------------------------------------------------------------------
// Liveness detection constants
// ---------------------------------------------------------------------------
// The CLIENT sends {"type":"ping"} every 5 s. The server responds with
// {"type":"pong"}. If a pong is missed, the client reconnects immediately.

// How often the client sends a ping to the server.
const PING_INTERVAL_MS = 5_000

// If no pong is received within this window, consider the connection
// dead and reconnect. This timeout is measured from the last ping sent,
// not from connect time, so the first timer tick always sends a ping
// instead of immediately declaring the socket stale.
const PONG_TIMEOUT_MS = 5_000

// Delay between reconnect attempts after a disconnect.
const RECONNECT_INTERVAL_MS = 5_000

// ---------------------------------------------------------------------------
// Foreground-resume liveness probe
// ---------------------------------------------------------------------------
// On iOS our BackgroundTimer falls back to plain setInterval — so when the
// JS thread is suspended (app backgrounded, screen locked, only BLE awake),
// the ping loop above stops firing entirely. The TCP socket can stay nominally
// open in the kernel for minutes while we receive zero frames, and then on
// foreground-return the user presses the camera button before the next ping
// tick runs. Result: the cloud's PHOTO_REQUEST gets written into a dead WS,
// the photo never lands, the SDK times out at 30s.
//
// The fix is to treat every transition into `active` as evidence we just
// woke up and the socket may be a zombie. We send a ping with a tighter
// deadline; if the pong does not land, we reconnect *immediately* rather
// than waiting for the next regular ping cycle.
const FOREGROUND_PROBE_PONG_TIMEOUT_MS = 2_500

// Max pongs we'll tolerate going missing in a row before reconnecting on the
// regular cycle. With PING_INTERVAL_MS=5_000 + PONG_TIMEOUT_MS=5_000, a
// single value of 1 already gives ~5–10s detection in the foreground; we
// keep a small allowance to ride out brief network glitches.
const MAX_CONSECUTIVE_MISSED_PONGS = 1

