// Liveness detection state
private lastPingAt: number = 0
private lastPongTime: number = 0
private awaitingPong: boolean = false
private consecutiveMissedPongs: number = 0
private pingInterval: ReturnType<typeof BackgroundTimer.setInterval> = 0
private foregroundProbeTimer: ReturnType<typeof setTimeout> | null = null
private appStateSubscription: {remove: () => void} | null = null
private lastAppState: AppStateStatus = AppState.currentState

private constructor() {
  super()
  GlobalEventEmitter.on("NO_ACTIVE_SESSION", this.handleNoActiveSession)
  // App-state listener: a foreground transition is the canonical "JS thread
  // just resumed, our timers may have been frozen for an unknown duration"
  // signal. Probe the WS aggressively rather than wait for the next tick.
  this.appStateSubscription = AppState.addEventListener("change", this.handleAppStateChange)
}

