tool_input.new_string:
private startLivenessMonitor() {
  this.stopLivenessMonitor()

  this.lastPingAt = 0
  this.lastPongTime = Date.now()
  this.awaitingPong = false
  this.consecutiveMissedPongs = 0

  this.sendPing()

  this.pingInterval = BackgroundTimer.setInterval(() => {
    if (!this.isConnected()) return

    if (this.awaitingPong) {
      const elapsed = Date.now() - this.lastPingAt
      if (elapsed >= PONG_TIMEOUT_MS) {
        // Outstanding ping timed out — count it and decide whether to give
        // up on this WS or just send the next probe. We use a tolerance
        // (MAX_CONSECUTIVE_MISSED_PONGS) because the iOS JS thread can
        // stutter for a tick or two on resume without the underlying
        // socket actually being dead.
        this.consecutiveMissedPongs += 1
        console.log(
          `WSM: pong missed (${this.consecutiveMissedPongs} in a row, elapsed=${elapsed}ms)`,
        )
        if (this.consecutiveMissedPongs > MAX_CONSECUTIVE_MISSED_PONGS) {
          this.reconnectNow(
            `pong timeout: ${this.consecutiveMissedPongs} consecutive misses (last elapsed=${elapsed}ms)`,
          )
          return
        }
        // Send the next ping immediately so we don't have to wait another
        // PING_INTERVAL_MS to retry.
        this.awaitingPong = false
        this.sendPing()
        return
      }
      return
    }

    this.sendPing()
  }, PING_INTERVAL_MS)
}

private sendPing() {
  if (!this.isConnected()) {
    return
  }

  this.lastPingAt = Date.now()
  this.awaitingPong = true

  try {
    this.webSocket?.send(JSON.stringify({type: "ping"}))
  } catch (error) {
    console.log("WSM: Error sending ping:", error)
  }
}

/**
 * Foreground-resume liveness probe. Called from the AppState listener
 * when the app re-enters `active` from any non-active state. iOS may have
 * suspended the JS thread (and our ping timer) for an arbitrarily long
 * time, so the regular pingInterval logic isn't sufficient on its own —
 * if there's a dead socket we want to find out before the user presses
 * the camera button, not 5 seconds after.
 */
private probeForForegroundResume() {
  if (this.foregroundProbeTimer) {
    clearTimeout(this.foregroundProbeTimer)
    this.foregroundProbeTimer = null
  }
  if (!this.isConnected()) {
    // If we're not connected, our regular reconnect interval is already
    // doing the right thing — just nudge it to retry now instead of
    // waiting for the next tick.
    this.actuallyReconnect()
    return
  }

  // Send a probe ping with a tight deadline. If the pong doesn't land
  // inside FOREGROUND_PROBE_PONG_TIMEOUT_MS, the socket is a zombie and
  // we reconnect immediately. We don't touch consecutiveMissedPongs here
  // because this is a one-shot wake-up check, not part of the steady-
  // state ping cycle.
  const probeStart = Date.now()
  this.lastPingAt = probeStart
  this.awaitingPong = true

  try {
    this.webSocket?.send(JSON.stringify({type: "ping"}))
  } catch (error) {
    console.log("WSM: Foreground probe send failed:", error)
    this.reconnectNow("foreground probe send failed")
    return
  }

  this.foregroundProbeTimer = setTimeout(() => {
    this.foregroundProbeTimer = null
    // If a pong landed strictly after we sent the probe, we're alive.
    if (this.lastPongTime >= probeStart) return
    const elapsed = Date.now() - probeStart
    this.reconnectNow(`foreground probe pong timeout (${elapsed}ms)`)
  }, FOREGROUND_PROBE_PONG_TIMEOUT_MS)
}

private handleAppStateChange = (next: AppStateStatus) => {
  const previous = this.lastAppState
  this.lastAppState = next
  if (next !== "active") return
  if (previous === "active") return // ignore active→active edge cases
  console.log(`WSM: AppState ${previous} → active — probing WS`)
  this.probeForForegroundResume()
}

/**
 * Stop the liveness monitor — clear the ping interval.
 */
private stopLivenessMonitor() {
  if (this.pingInterval) {
    BackgroundTimer.clearInterval(this.pingInterval)
    this.pingInterval = 0
  }
  if (this.foregroundProbeTimer) {
    clearTimeout(this.foregroundProbeTimer)
    this.foregroundProbeTimer = null
  }

  this.awaitingPong = false
  this.lastPingAt = 0
  this.consecutiveMissedPongs = 0
}

